// partialy generated by Copilot
import { validatorUtilsMocks, getEmailIsValidMock } from '@pulse/core/mocks'
import { getEmailError, getPasswordError } from './LoginClient.utils'

vi.mock('@pulse/core/utils/validator', () => validatorUtilsMocks)

describe('test LoginClient.utils', () => {
  const requiredErrorMessage = 'Email is required'
  const invalidErrorMessage = 'Invalid email format'

  describe('getEmailError', () => {
    const testCases = [
      {
        email: '',
        isValid: false,
        expected: requiredErrorMessage,
        description: 'should return required error message when email is empty',
      },
      {
        email: 'invalid-email',
        isValid: false,
        expected: invalidErrorMessage,
        description: 'should return invalid error message for invalid email',
      },
      {
        email: 'valid.email@example.com',
        isValid: true,
        expected: '',
        description: 'should return an empty string for a valid email',
      },
    ]

    it.each(testCases)('$description', ({
      email,
      expected,
      isValid,
    }) => {
      getEmailIsValidMock.mockReturnValue(isValid)

      const result = getEmailError(email, requiredErrorMessage, invalidErrorMessage)
      expect(result).toBe(expected)
    })
  })

  describe('getPasswordError', () => {
    const requiredErrorMessage = 'Password is required'
    const testCases = [
      {
        password: '',
        expected: requiredErrorMessage,
        description: 'should return required error message when password is empty',
      },
      {
        password: 'password123',
        expected: '',
        description: 'should return an empty string when password is NOT empty',
      },
    ]
    it.each(testCases)('$description', ({
      password,
      expected,
    }) => {
      const result = getPasswordError(password, requiredErrorMessage)
      expect(result).toBe(expected)
    })
  })
})
